}
const median=xs=>{xs.sort((a,b)=>a-b);return (xs[17]+xs[18])/2;};
const summary=captures[0].results.map(({name})=>{const pick=v=>median(captures.filter(c=>c.variant===v).flatMap(c=>c.results.find(r=>r.name===name).samples));const before=pick('before'),after=pick('after');return{name,before,after,changePercent:(after/before-1)*100};});
