import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {reactive,batch,createEffectScope,watch,flushSync} from '../../packages/reactive/dist/index.js';
import {whenEffectScopeResumed} from '../../packages/reactive/dist/internal/scopes.js';
import {taskAwait,trackTaskOwner} from '../../packages/core/dist/tasks/resources.js';
import {isJsonSafe as serverSafe} from '../../packages/server/dist/protocol.js';
import {isJsonSafe as hydrateSafe} from '../../packages/hydrate/dist/validation.js';
import {ownRegistryEntry} from '../../packages/server/dist/registry-entry.js';
import {composeExactExecutorContract,defineExactOperationContract} from '../../packages/server/dist/executor-contract.js';
import {exactComponentContract,exactComponentType} from '../../packages/core/dist/framework/component-contracts.js';
import {createExactFrameworkFixtureArtifact} from '@exactjs/core/testing';
const results=[];
function sync(name,iterations,fn){const samples=[];for(let s=-3;s<9;s++){const start=performance.now();for(let i=0;i<iterations;i++)fn(i);const ms=(performance.now()-start)/iterations;if(s>=0)samples.push(ms);}results.push({name,iterations,samples});}
async function asyncMeasure(name,iterations,fn){const samples=[];for(let s=-3;s<9;s++){const start=performance.now();for(let i=0;i<iterations;i++)await fn(i);const ms=(performance.now()-start)/iterations;if(s>=0)samples.push(ms);}results.push({name,iterations,samples});}
let consumed=0;
for(const kind of ['primitive','object']){
  const key=kind==='primitive'?'key':{};
  const map=reactive(new Map([[key,1]]));
  sync(`identity/${kind}/hot-read`,100000,()=>{consumed+=map.get(key);});
  sync(`identity/${kind}/cold-map`,5000,()=>{consumed+=reactive(new Map([[key,1]])).get(key);});
  let seen;
  const stop=watch(()=>{seen=map.get(key);});
  sync(`identity/${kind}/observed-reinsert`,2000,i=>{map.delete(key);map.set(key,i);flushSync();assert.equal(seen,i);});stop();
}
const rollback=new Error('rollback');
for(const kind of ['Map','Set'])for(const position of ['head','middle','tail']) {
  const keys=Array.from({length:10000},(_,i)=>i);const key=position==='head'?0:position==='tail'?9999:5000;
  const collection=reactive(kind==='Map'?new Map(keys.map(k=>[k,k])):new Set(keys));
  sync(`order/${kind}/${position}/rollback`,50,()=>{try{batch(()=>{collection.delete(key);throw rollback;});}catch(e){assert.equal(e,rollback);}});
  assert.deepEqual([...collection.keys()],keys);
}
for(const mode of ['resume','abort','no-signal']){
  await asyncMeasure(`scope/${mode}`,1000,async()=>{
    const scope=createEffectScope();scope.pause();const c=mode==='no-signal'?undefined:new AbortController();
    try{const waiting=whenEffectScopeResumed(scope,c?.signal);if(mode==='abort')c.abort();else scope.resume();await waiting;assert.equal(scope.resumeWaiters.size,0);}finally{scope.stop();}
  });
}
for(const mode of ['fulfilled','rejected','paused-fulfilled','paused-rejected','cancel-paused']){
  const scope=createEffectScope();const c=new AbortController();trackTaskOwner(c.signal,{scope});
  try{await asyncMeasure(`task/${mode}`,1000,async()=>{
    const controller=mode==='cancel-paused'?new AbortController():c;
    if(controller!==c)trackTaskOwner(controller.signal,{scope});
    if(mode.startsWith('paused')||mode==='cancel-paused')scope.pause();
    const rejected=mode.endsWith('rejected');
    const waiting=taskAwait(controller.signal,rejected?Promise.reject(rollback):Promise.resolve(1)).then(v=>({v}),e=>({e}));
    if(scope.paused){await Promise.resolve();if(mode==='cancel-paused')controller.abort();else scope.resume();}
    const result=await waiting;
    if(mode==='cancel-paused'){assert.equal(result.e?.name,'AbortError');scope.resume();}
    else if(rejected)assert.equal(result.e,rollback);else assert.equal(result.v,1);
  });}finally{c.abort();scope.stop();}
}
for(const [name,validate] of [['server',serverSafe],['hydrate',hydrateSafe]]){
  for(const kind of ['numeric-map','string-map','unicode-map','set']){
    const keys=Array.from({length:1000},(_,i)=>i);
    const value=kind==='set'?new Set(keys):new Map(keys.map(k=>[kind==='numeric-map'?k:kind==='unicode-map'?`κλειδί-${k}`:`key-${k}`,k]));
    sync(`validation/${name}/${kind}/valid`,100,()=>assert.equal(validate(value),true));
    sync(`validation/${name}/${kind}/node-reject`,5000,()=>assert.equal(validate(value,{maxNodes:4}),false));
  }
  const largeKey=new Map([['x'.repeat(10000),0]]);
  sync(`validation/${name}/key-byte-reject`,1000,()=>assert.equal(validate(largeKey,{maxBytes:16}),false));
}
const registry=Object.fromEntries(Array.from({length:1000},(_,i)=>[`op-${i}`,i]));
for(const [name,lookup] of [['hasOwn',ownRegistryEntry],['descriptor',(r,k)=>r&&Object.getOwnPropertyDescriptor(r,k)?r[k]:undefined]]){
  sync(`registry/${name}/own-hit`,100000,i=>{consumed+=lookup(registry,`op-${i%1000}`);});
  sync(`registry/${name}/inherited-miss`,100000,()=>assert.equal(lookup(registry,'toString'),undefined));
}
const continuations=Array.from({length:1000},(_,i)=>defineExactOperationContract(`op-${i}`,{componentId:'Bench'}));
const component=Object.assign(()=>()=>undefined,{[exactComponentType]:'Bench',[exactComponentContract]:{version:1,placement:'server',role:'executor',implementations:[],continuations,executors:[],boundaries:[]}});
createExactFrameworkFixtureArtifact(component,'Bench','server');
sync('registry/compose/generated-1000',100,()=>{const r=composeExactExecutorContract([component]);assert.equal(Object.keys(r.invocations).length,1000);});
const endpoints={invocations:Object.fromEntries(continuations.map(c=>[c.id,'/actions']))};
sync('registry/compose/endpoints-1000',100,()=>{const r=composeExactExecutorContract([],{endpoints});assert.equal(Object.keys(r.endpoints.invocations).length,1000);});
sync('registry/compose/explicit-1000',100,()=>{const r=composeExactExecutorContract([],{invocations:registry});assert.equal(Object.keys(r.invocations).length,1000);});
writeFileSync(process.argv[2],JSON.stringify({variant:process.env.AUDIT_VARIANT,node:process.version,results,consumed}));

