for(const kind of ['primitive','object'])for(let sample=0;sample<5;sample++){
  globalThis.retained=undefined;global.gc();global.gc();
  const before=process.memoryUsage().heapUsed;
  globalThis.retained=Array.from({length:20000},()=>{const key=kind==='primitive'?'key':{};const map=reactive(new Map([[key,1]]));map.get(key);return map;});
  global.gc();global.gc();
  heap.push({kind,sample,bytesPerCollection:(process.memoryUsage().heapUsed-before)/20000});
}
globalThis.retained=undefined;global.gc();
const promises=[];
for(const mode of ['fulfilled','rejected','paused-fulfilled','paused-rejected']){
  const scope=createEffectScope();const controller=new AbortController();trackTaskOwner(controller.signal,{scope});
  let count=0;const hook=createHook({init(id,type){if(type==='PROMISE')count++;}});
  try{hook.enable();for(let i=0;i<1000;i++){
    if(mode.startsWith('paused'))scope.pause();
    const waiting=taskAwait(controller.signal,mode.endsWith('rejected')?Promise.reject(0):Promise.resolve(1)).catch(()=>{});
    if(scope.paused){await Promise.resolve();scope.resume();}
