  }}finally{hook.disable();controller.abort();scope.stop();}
  promises.push({mode,count,iterations:1000});
}
writeFileSync(process.argv[2],JSON.stringify({variant:process.env.AUDIT_VARIANT,node:process.version,heap,promises}));

